const REGISTER = {
  storage_gdrive: { version: "1.0.0", release_state: "draft", readback_supported: true },
  storage_sharepoint: { version: "1.0.0", release_state: "draft", readback_supported: true },
  ocr_default: { version: "1.0.0", release_state: "draft", readback_supported: false },
  llm_default: { version: "1.0.0", release_state: "draft", readback_supported: false },
  drafts_internal: { version: "1.0.0", release_state: "draft", readback_supported: true },
  report_internal: { version: "1.0.0", release_state: "draft", readback_supported: true },
  test: { version: "1.0.0", release_state: "draft", readback_supported: true }
};
const KONTEXTE = ["privat", "arbeitgeber_visolva"];
const ergebnis = [];
for (const item of $input.all()) {
  const kontext = item.json.context_id;
  const werkzeug = item.json.tool_id;
  const version = item.json.tool_version;
  const klasse = item.json.risk_class;
  let freigegeben = false;
  let grund = "";
  let code = "";

  const eintrag = Object.prototype.hasOwnProperty.call(REGISTER, werkzeug) ? REGISTER[werkzeug] : null;

  if (KONTEXTE.indexOf(kontext) === -1) { code = "invalid_context"; grund = "context_id nicht im Register"; }
  else if (eintrag === null) { code = "tool_not_registered"; grund = "Werkzeug nicht registriert: " + String(werkzeug); }
  else if (eintrag.version !== version) { code = "tool_version_mismatch"; grund = "Vertragsversion weicht ab, erwartet " + eintrag.version; }
  else if (["A", "B", "C"].indexOf(klasse) === -1) { code = "risk_class_missing"; grund = "risk_class fehlt oder ist unzulaessig"; }
  else if (klasse === "C" && (!item.json.approval_id || item.json.approval_status !== "approved")) {
    code = "approval_missing";
    grund = "Klasse C ohne gueltige Freigabe";
  }
  else if (eintrag.release_state !== "approved") {
    code = "tool_not_released";
    grund = "Werkzeug steht auf " + eintrag.release_state + ". Freigabe erfolgt erst nach dem praktischen Nachweis des zugehoerigen Subworkflows.";
  }
  else { freigegeben = true; }

  ergebnis.push({ json: {
    invocation_allowed: freigegeben,
    gate_code: freigegeben ? "allowed" : code,
    reason: grund,
    tool_id: werkzeug || null,
    tool_version: version || null,
    readback_supported: eintrag ? eintrag.readback_supported : null,
    risk_class: klasse || null,
    context_id: kontext || null,
    trace_id: item.json.trace_id || null
  } });
}
return ergebnis;
